    Q('today {#}% · no change {#}%', 'hoy {1} % · sin cambio {2} %', '今天 {1}% · 不变 {2}%', 'dziś {1}% · bez zmian {2}%'), Q('Your plan: {#}% of pay', 'Tu plan: {1} % del sueldo', '你的方案：工资的 {1}%', 'Twój plan: {1}% pensji'),
